fn solve(input: Vec<char>) -> Vec<char> {
    // Extract first two digits
    let first_digit = input[0];
    let second_digit = input[1];
    
    // Define mapping from digit to good count
    let good_count = |c: char| -> u32 {
        match c {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // Should not happen based on problem constraints
        }
    };
    
    // Calculate product
    let product = good_count(first_digit) * good_count(second_digit);
    
    // Convert product to string and add newline
    let mut result: Vec<char> = product.to_string().chars().collect();
    result.push('\n');
    
    result
}